def make_F(n: int, m: int, seed: int = 12345):
    F = np.empty((n, m))
    s = seed
    for i in range(n):
        for j in range(m):
            s = (s * 1103515245 + 12345) % 2147483648
            F[i, j] = float(s % 20001 - 10000) * 0.000123 * float(j + 1)
    return F

def make_y(n: int):
    return np.array([(i * 7 % 5) % 2 for i in range(n)])

nan = float("nan")

def close(got, exp: List[float], tol: float) -> bool:
    ok = True
    if got.size != len(exp):
        print("size mismatch", got.size, len(exp))
        return False
    g = got.ravel()
    for i in range(len(exp)):
        a = g[i]
        b = exp[i]
        if a != a and b != b:
            continue
        if abs(a - b) > tol + tol * abs(b) or (a != a) != (b != b):
            print("mismatch at", i, a, b)
            ok = False
    return ok

