@test
def test_ewm():
    assert close((df.ewm(com=1.5, adjust=True, ignore_na=False).mean()).to_numpy(), E_mean10, 1e-12)
    assert close((df.ewm(alpha=0.3, adjust=True, ignore_na=False).sum()).to_numpy(), E_sum10, 1e-12)
    assert close((df.ewm(span=5, min_periods=2, adjust=True, ignore_na=False).var()).to_numpy(), E_var10, 1e-12)
    assert close((df.ewm(halflife=3, adjust=True, ignore_na=False).std(True)).to_numpy(), E_std10, 1e-12)
    assert close((df.ewm(com=1.5, adjust=True, ignore_na=True).mean()).to_numpy(), E_mean11, 1e-12)
    assert close((df.ewm(alpha=0.3, adjust=True, ignore_na=True).sum()).to_numpy(), E_sum11, 1e-12)
    assert close((df.ewm(span=5, min_periods=2, adjust=True, ignore_na=True).var()).to_numpy(), E_var11, 1e-12)
    assert close((df.ewm(halflife=3, adjust=True, ignore_na=True).std(True)).to_numpy(), E_std11, 1e-12)
    assert close((df.ewm(com=1.5, adjust=False, ignore_na=False).mean()).to_numpy(), E_mean00, 1e-12)
    assert close((df.ewm(span=5, min_periods=2, adjust=False, ignore_na=False).var()).to_numpy(), E_var00, 1e-12)
    assert close((df.ewm(halflife=3, adjust=False, ignore_na=False).std(True)).to_numpy(), E_std00, 1e-12)
    assert close((df.ewm(com=1.5, adjust=False, ignore_na=True).mean()).to_numpy(), E_mean01, 1e-12)
    assert close((df.ewm(span=5, min_periods=2, adjust=False, ignore_na=True).var()).to_numpy(), E_var01, 1e-12)
    assert close((df.ewm(halflife=3, adjust=False, ignore_na=True).std(True)).to_numpy(), E_std01, 1e-12)
    assert close((df[["a", "b"]].ewm(com=2.0).cov(df["c"])).to_numpy(), E_cov, 1e-12)
    assert close((df[["a", "b"]].ewm(com=2.0).corr(df["c"])).to_numpy(), E_corr, 1e-12)
    assert close((df[["a", "b"]].rolling(6, min_periods=3).cov(df["c"])).to_numpy(), E_rcov, 1e-12)
    assert close((df[["a", "b"]].rolling(6, min_periods=3).corr(df["c"])).to_numpy(), E_rcorr, 1e-12)
    assert close((df.rolling(7, min_periods=4).quantile(0.37, "linear")).to_numpy(), E_rqlinear, 1e-12)
    assert close((df.rolling(7, min_periods=4).quantile(0.37, "lower")).to_numpy(), E_rqlower, 1e-12)
    assert close((df.rolling(7, min_periods=4).quantile(0.37, "higher")).to_numpy(), E_rqhigher, 1e-12)
    assert close((df.rolling(7, min_periods=4).quantile(0.37, "nearest")).to_numpy(), E_rqnearest, 1e-12)
    assert close((df.rolling(7, min_periods=4).quantile(0.37, "midpoint")).to_numpy(), E_rqmidpoint, 1e-12)
test_ewm()
